mapper.select:
select id, stock_date, mix_area, material_name, stock_num, remark, del_flag, create_by, create_time, update_by, update_time, bar_code,valid_time, stock_weight from t_lhfl_glue_stock where del_flag = '0' and stock_date = #{stockDate} and mix_area = #{mixArea} and INSTR(material_name, #{materialName}) > 0
order by stock_date desc,valid_time asc
order by ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber} row_numbers, #{data.stockDate,jdbcType=TIMESTAMP} stock_date, #{data.barCode,jdbcType= VARCHAR} bar_code
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_lhfl_glue_stock m inner join temp_table t on m.stock_date = t.stock_date and m.bar_code = t.bar_code and m.del_flag ='0'

mapper.insert:
insert into t_lhfl_glue_stock (id,stock_date,mix_area,material_name,stock_num,remark,del_flag,create_by,create_time,update_by,update_time,bar_code,valid_time,stock_weight) select NULL id, x.* from (
select #{lhflGlueStock.stockDate,jdbcType=TIMESTAMP} stock_date, #{lhflGlueStock.mixArea,jdbcType= VARCHAR} mix_area, #{lhflGlueStock.materialName,jdbcType= VARCHAR} material_name, #{lhflGlueStock.stockNum,jdbcType=DOUBLE} stock_num, #{lhflGlueStock.remark,jdbcType= VARCHAR} remark, #{lhflGlueStock.delFlag,jdbcType= VARCHAR} del_flag, #{lhflGlueStock.createBy,jdbcType= VARCHAR} create_by, #{lhflGlueStock.createTime,jdbcType=TIMESTAMP} create_time, #{lhflGlueStock.updateBy,jdbcType= VARCHAR} update_by, #{lhflGlueStock.updateTime,jdbcType=TIMESTAMP} update_time, #{lhflGlueStock.barCode,jdbcType=VARCHAR} bar_code,#{lhflGlueStock.validTime, jdbcType=TIMESTAMP} valid_time, #{lhflGlueStock.stockWeight,jdbcType=DOUBLE} stock_weight
) x
